(function(root){
  'use strict';
  const fold=value=>String(value||'').toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu,'');
  function enrichLessons(list,data){
    return list.map(lesson=>{
      const extra=data.lessons?.[lesson.id];if(!extra)return lesson;
      const sources=(data.sources||[]).filter(s=>s.lessons.includes(lesson.id));
      const questions=(extra.questions||[]).map(q=>({...q,stem:q.case+'\n\n'+q.prompt,explanation:q.explanation||q.optionExplanations?.map((text,i)=>String.fromCharCode(65+i)+': '+text).join(' ')}));
      return {...lesson,minutes:extra.minutes||lesson.minutes,recall:extra.recall||lesson.recall,technical:{...extra,cards:sources},legacyQuestions:lesson.questions,questions:questions.length?questions:lesson.questions,objectives:[...lesson.objectives,...(extra.objectives||[])],sources:[...lesson.sources,...sources.filter(s=>!lesson.sources.some(old=>old.url===s.url)).map(s=>({label:s.title+' · '+s.reference,url:s.url}))]};
    });
  }
  function filterSources(sources,query='',axis='all'){
    const term=fold(query);return sources.filter(s=>(axis==='all'||s.lessons.includes(axis))&&fold([s.title,s.reference,s.rule,s.distinction,s.application,...(s.points||[]).map(p=>p.article+' '+p.focus),...(s.keywords||[])].join(' ')).includes(term));
  }
  function searchableLesson(lesson,data){return [lesson.title,lesson.indicator,lesson.summary,...(lesson.technical?.sections||[]).map(s=>s.title+' '+s.text),...(data.sources||[]).filter(s=>s.lessons.includes(lesson.id)).map(s=>s.title+' '+s.reference+' '+s.rule+' '+(s.points||[]).map(p=>p.article+' '+p.focus).join(' '))].join(' ')}
  function sourceHTML(source,lessons,esc){
    return `<details class="norm-card" id="norma-${esc(source.id)}"><summary><span class="norm-type">${source.kind==='norma'?'NORMA JURÍDICA':source.kind==='técnica'?'REFERENCIA TÉCNICA':'MARCO DE ESTUDIO'}</span><strong>${esc(source.title)}</strong><span class="norm-reference">${esc(source.reference)}</span></summary><div class="norm-body">${source.points?.length?`<h4>Mapa de artículos para estudiar</h4><dl class="article-map">${source.points.map(point=>`<div><dt>${esc(point.article)}</dt><dd>${esc(point.focus)}</dd></div>`).join('')}</dl>`:''}<h4>La regla que debes dominar</h4><p>${esc(source.rule)}</p><h4>La distinción que cambia la respuesta</h4><p>${esc(source.distinction)}</p><h4>Aplicación al trabajo de apoyo</h4><p>${esc(source.application)}</p><div class="line wrap norm-links"><a href="${esc(source.url)}" target="_blank" rel="noopener">Consultar fuente oficial ↗</a>${(source.relatedUrls||[]).map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener">Lectura complementaria ${i+1} ↗</a>`).join('')}</div>${lessons?`<div class="line wrap norm-lessons">${source.lessons.map(id=>{const l=lessons.find(l=>l.id===id);return l?`<button class="text-btn" data-action="lesson" data-value="${esc(id)}">Estudiar: ${esc(l.title)} →</button>`:''}).join('')}</div>`:''}</div></details>`;
  }
  function lessonHTML(lesson,ls,esc){
    const t=lesson.technical;if(!t)return '';
    return `<section class="technical-expansion" id="profundizacion"><div class="technical-heading"><span class="eyebrow">AMPLIACIÓN TÉCNICA · 15 OCT 2026</span><h2>Del concepto al fundamento</h2><p>${ls.read?'Tu avance anterior se conserva. Repasa esta ampliación y marca las nuevas metas del tema.':'Estudia las reglas, las diferencias entre conceptos y los datos que determinan una actuación.'}</p></div><nav class="technical-toc" aria-label="Apartados de profundización">${t.sections.map((s,i)=>`<a href="#apartado-${esc(lesson.id)}-${i}" data-study-anchor="apartado-${esc(lesson.id)}-${i}">${esc(s.title)}</a>`).join('')}</nav>${t.sections.map((s,i)=>`<section class="study-section technical-section" id="apartado-${esc(lesson.id)}-${i}"><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p>${s.reference?`<p class="technical-reference">${esc(s.reference)}</p>`:''}</section>`).join('')}${t.glossary?.length?`<section class="technical-glossary"><h3>Vocabulario que debes manejar</h3><dl>${t.glossary.map(g=>`<div><dt>${esc(g.term)}</dt><dd>${esc(g.definition)}</dd></div>`).join('')}</dl></section>`:''}${t.cards.length?`<section class="lesson-norms"><div class="spread wrap"><h2>Normas y referencias de este eje</h2><button class="text-btn" data-action="navigate" data-value="normativa/${esc(lesson.id)}">Abrir biblioteca →</button></div><p class="muted">Abre cada ficha: regla, diferencia frecuente, aplicación y enlace a la fuente.</p>${t.cards.map(s=>sourceHTML(s,null,esc)).join('')}</section>`:''}<p class="technical-method">Las preguntas funcionales aplican casos originales. Las referencias apoyan tus indicadores y no predicen el contenido reservado del examen.</p></section>`;
  }
  function sourceResultsHTML(data,lessons,esc,query='',axis='all'){
    const rows=filterSources(data.sources,query,axis);
    return `<p class="norm-count" role="status">${rows.length} ${rows.length===1?'ficha encontrada':'fichas encontradas'}</p>${rows.length?rows.map(s=>sourceHTML(s,lessons,esc)).join(''):'<div class="empty"><h3>No hay coincidencias</h3><p>Prueba con el número de la norma, un artículo o un concepto; también puedes cambiar el eje.</p></div>'}`;
  }
  function libraryHTML(data,lessons,esc,axis='all'){
    if(!lessons.some(l=>l.id===axis))axis='all';
    return `<div class="page-heading"><h1>Tu biblioteca normativa</h1><p>Conoce la regla, reconoce la excepción y aprende a usarla en un caso.</p></div><section class="panel norm-intro"><span class="pill green">${data.sources.length} fichas · Revisado el 15 de octubre de 2026</span><h2>Una base técnica para tus 22 indicadores</h2><p>Constitución, DIAN y tributos, archivo, peticiones, datos personales y deberes del servidor. Se incluyen referencias de ofimática para los ejes que las requieren.</p><p class="norm-cutoff"><strong>Corte de preparación:</strong> normas vigentes y expedidas antes del 19 de junio de 2026, según la guía oficial. Los textos consolidados pueden mostrar modificaciones posteriores: comprueba sus notas de vigencia.</p><p class="muted">La selección profundiza tus indicadores; no es una lista oficial exhaustiva de leyes que preguntará el concurso.</p><div class="line wrap" style="margin-top:18px"><button class="btn primary" data-action="start-normative">Practicar 12 casos normativos</button><a class="text-btn" href="${esc(data.guide)}" target="_blank" rel="noopener">Guía y ejemplos oficiales ↗</a></div></section><section class="panel norm-library"><div class="norm-filters"><label class="field">Norma o concepto<input id="norm-search" class="search-input" type="search" placeholder="Buscar: 1755, artículo 14, RUT, TRD, reserva…"></label><label class="field">Eje de estudio<select id="norm-axis"><option value="all">Todos los ejes</option>${lessons.map(l=>`<option value="${esc(l.id)}" ${axis===l.id?'selected':''}>${esc(l.indicator)}</option>`).join('')}</select></label></div><div id="norm-results">${sourceResultsHTML(data,lessons,esc,'',axis)}</div></section>`;
  }
  root.RutaStudy={enrichLessons,filterSources,searchableLesson,fold,lessonHTML,libraryHTML,sourceResultsHTML};
})(window);
